window.BANCO = window.BANCO || [];
window.BANCO.push({"id":"trebep","nombre":"TREBEP, Estatuto Básico del Empleado Público","bloques":[{"id":"ambito","nombre":"Ámbito de aplicación (arts. 1 a 7)"},{"id":"clases","nombre":"Clases de personal (arts. 8 a 13)"},{"id":"derechos","nombre":"Derechos y deberes (arts. 14 a 20)"},{"id":"retribuciones","nombre":"Retribuciones, jornada y permisos (arts. 21 a 30)"},{"id":"negociacion","nombre":"Negociación colectiva y representación (arts. 31 a 38)"},{"id":"deberes","nombre":"Deberes y código de conducta (arts. 52 a 54)"},{"id":"acceso","nombre":"Acceso al empleo público (arts. 55 a 62)"},{"id":"adquisicion","nombre":"Adquisición y pérdida de la relación de servicio (arts. 63 a 68)"},{"id":"provision","nombre":"Ordenación de la actividad profesional y provisión (arts. 69 a 84)"},{"id":"situaciones","nombre":"Situaciones administrativas (arts. 85 a 92)"},{"id":"disciplina","nombre":"Régimen disciplinario (arts. 93 a 98)"},{"id":"otros","nombre":"Otras normas relacionadas"}],"calendarios":{},"casos":[],"preguntas":[{"id":"au-01-001","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 1) - arts. 1 a 8","n":1,"enunciado":"El Estatuto Básico del Empleado Público tiene por objeto:","opciones":["Establecer las bases del régimen estatutario de todos los funcionarios públicos.","Establecer las bases del régimen estatutario de los funcionarios públicos incluidos en su ámbito de aplicación.","Establecer las bases del régimen estatutario de todos los empleados públicos.","Establecer las bases del régimen estatutario del personal laboral incluido en su ámbito de aplicación."],"bloque":"ambito","precepto":"Art. 1.1 del TREBEP","correcta":1,"justificaciones":["No. El Estatuto no regula a todos los funcionarios, solo a los incluidos en su ámbito de aplicación. Hay funcionarios (jueces, militares, Cortes...) que se rigen por su propia ley.","Es esta. El **art. 1.1** dice que el Estatuto fija las bases del régimen estatutario de los funcionarios públicos incluidos en su ámbito de aplicación.","No. Te han cambiado “funcionarios” por “empleados públicos” y “incluidos en su ámbito” por “todos”. Las bases estatutarias son para funcionarios; el personal laboral se trata aparte (art. 1.2).","No. El personal laboral solo aparece en el **art. 1.2**, para determinar las normas que se le aplican. El objeto principal (art. 1.1) es el régimen estatutario de los funcionarios."]},{"id":"au-01-002","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 1) - arts. 1 a 8","n":2,"enunciado":"Señale la opción incorrecta. El TREBEP se aplica directamente a:","opciones":["El personal laboral de las Universidades Públicas.","El personal laboral de la Administración General del Estado.","El personal funcionario de las Administraciones de las Comunidades Autónomas.","El personal funcionario de los órganos constitucionales del Estado."],"bloque":"ambito","precepto":"Arts. 2 y 4 del TREBEP","correcta":3,"justificaciones":["Es verdadera, así que no se marca. Las Universidades Públicas están en el ámbito del **art. 2.1.e**, y su personal laboral se rige por el Estatuto en lo que proceda.","Es verdadera, así que no se marca. La Administración General del Estado es la primera del **art. 2.1.a**.","Es verdadera, así que no se marca. Las Administraciones de las comunidades autónomas están en el **art. 2.1.b**.","Esta es la falsa, y por eso es la que hay que marcar. El personal funcionario de los demás órganos constitucionales del Estado está en el **art. 4.b**: el Estatuto solo se le aplica directamente si su legislación específica lo dispone."]},{"id":"au-01-003","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 1) - arts. 1 a 8","n":3,"enunciado":"Según lo establecido en el artículo 3.2 del TREBEP, los Cuerpos de Policía Local se rigen por este Estatuto y por la legislación de las comunidades autónomas:","opciones":["Exclusivamente.","Solo cuando así lo disponga su legislación específica.","Excepto en lo establecido para ellos en la Ley Orgánica de Fuerzas y Cuerpos de Seguridad.","Excepto en lo establecido para ellos en la Ley Reguladoras de las Bases del Régimen Local."],"bloque":"ambito","precepto":"Art. 3.2 del TREBEP","correcta":2,"justificaciones":["No. El **art. 3.2** dice que se rigen “también” por el Estatuto y por la legislación autonómica, pero con una excepción, así que no es “exclusivamente”.","No. No depende de lo que diga su legislación específica. Se rigen por el Estatuto directamente, salvo lo que la ley de fuerzas y cuerpos de seguridad regule para ellos.","Es esta. Excepto en lo establecido para ellos en la **Ley Orgánica 2/1986** de Fuerzas y Cuerpos de Seguridad (art. 3.2).","No. La excepción no es la ley de bases de régimen local, sino la Ley Orgánica 2/1986, de Fuerzas y Cuerpos de Seguridad."]},{"id":"au-01-004","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 1) - arts. 1 a 8","n":4,"enunciado":"Señale la respuesta correcta en relación con el ámbito de aplicación del TREBEP:","opciones":["No será de aplicación al personal investigador al servicio de las Administraciones Públicas.","El personal docente y el personal estatutario de los Servicios de Salud se regirán únicamente por su legislación específica.","Cada vez que este Estatuto haga mención al personal funcionario de carrera se entenderá comprendido el personal estatutario de los Servicios de Salud.","El presente Estatuto se aplicará directamente a todo el personal de las Administraciones Públicas."],"bloque":"ambito","precepto":"Art. 2.4 del TREBEP","correcta":2,"justificaciones":["No. El **art. 2.2** permite dictar normas singulares para el personal de investigación, pero el Estatuto sí se les aplica.","No. El personal docente y el estatutario se rigen por su legislación específica y además por lo previsto en el Estatuto (con algunas excepciones), no “únicamente” por la específica (**art. 2.3**).","Es esta. El **art. 2.4** dice que cada vez que el Estatuto menciona al personal funcionario de carrera se entiende comprendido el personal estatutario de los Servicios de Salud.","No. No se aplica directamente a todo el personal. Hay personal con legislación específica propia (**art. 4**) y el personal laboral solo en lo que proceda."]},{"id":"au-01-005","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 1) - arts. 1 a 8","n":5,"enunciado":"Según el artículo 3 del TREBEP, el personal funcionario de las entidades locales se rige, con respeto a la autonomía local, por:","opciones":["La legislación estatal que resulte de aplicación, de la que no forma parte este Estatuto, y por la de las comunidades autónomas.","La legislación estatal que resulte de aplicación, de la que forma parte este Estatuto, y por la de las comunidades autónomas.","Exclusivamente por este Estatuto.","Exclusivamente por la legislación de las comunidades autónomas."],"bloque":"ambito","precepto":"Art. 3.1 del TREBEP","correcta":1,"justificaciones":["No. Te han dicho que el Estatuto no forma parte de la legislación estatal aplicable. Sí forma parte.","Es esta. El **art. 3.1** dice que se rigen por la legislación estatal que resulte de aplicación, de la que forma parte este Estatuto, y por la de las comunidades autónomas, con respeto a la autonomía local.","No. No es “exclusivamente” el Estatuto: también cuenta la legislación autonómica.","No. No es solo la legislación autonómica: también se aplica la estatal, y el Estatuto es parte de ella."]},{"id":"au-01-006","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 1) - arts. 1 a 8","n":6,"enunciado":"El TREBEP se aplica directamente al personal del Banco de España:","opciones":["En todos los aspectos que la Ley regula.","Cuando así lo disponga su legislación específica.","No se les aplica en ningún supuesto.","En su totalidad, a excepción del régimen sancionador."],"bloque":"ambito","precepto":"Art. 4.h del TREBEP","correcta":1,"justificaciones":["No. El personal del Banco de España está en la lista del **art. 4**, así que el Estatuto no se le aplica en todos los aspectos.","Es esta. El **art. 4.h** incluye al personal del Banco de España y del Fondo de Garantía de Depósitos entre quienes solo se rigen directamente por el Estatuto cuando lo disponga su legislación específica.","No. No es “en ningún supuesto”: si su legislación específica lo dispone, se aplica.","No. No hay una excepción solo para el régimen sancionador. Todo depende de lo que disponga su legislación específica."]},{"id":"au-01-007","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 1) - arts. 1 a 8","n":7,"enunciado":"De acuerdo con lo establecido en su artículo 2, el TREBEP será de aplicación directa:","opciones":["Al personal funcionario de las Cortes Generales.","Al personal laboral al servicio de las Administraciones Públicas de las ciudades de Ceuta y Melilla.","Al Personal de las Fuerzas y Cuerpos de Seguridad del Estado.","Al personal laboral de entidades de derecho privado dependientes de cualquiera de las Administraciones Públicas."],"bloque":"ambito","precepto":"Art. 2.1.b del TREBEP","correcta":1,"justificaciones":["No. El personal funcionario de las Cortes Generales está en el **art. 4.a**: solo se le aplica el Estatuto si su legislación específica lo dispone.","Es esta. El **art. 2.1.b** incluye a las Administraciones de las comunidades autónomas y de las ciudades de Ceuta y Melilla, y se aplica a su personal laboral en lo que proceda.","No. El personal de las Fuerzas y Cuerpos de Seguridad del Estado está en el **art. 4.e**.","No. El **art. 2.1.d** habla de entidades de derecho público. Las entidades de derecho privado no están en esa lista."]},{"id":"au-01-008","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 1) - arts. 1 a 8","n":8,"enunciado":"Conforme al artículo 4 del TREBEP, las disposiciones de este Estatuto solo se aplicarán directamente cuando así lo disponga su legislación específica al siguiente personal:","opciones":["Personal retribuido por arancel.","Personal docente.","Personal investigador.","Personal estatutario de los Servicios de Salud."],"bloque":"ambito","precepto":"Art. 4.f del TREBEP","correcta":0,"justificaciones":["Es esta. El personal retribuido por arancel está en la lista del **art. 4.f**: el Estatuto solo se le aplica directamente si su legislación específica lo dispone.","No. El personal docente no está en el art. 4. Se rige por su legislación específica y por el Estatuto, salvo algunos preceptos (**art. 2.3**).","No. Para el personal de investigación el **art. 2.2** solo permite dictar normas singulares. No está en el art. 4.","No. El personal estatutario de los Servicios de Salud está en el **art. 2.3**, no en el art. 4."]},{"id":"au-01-009","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 1) - arts. 1 a 8","n":9,"enunciado":"Las disposiciones del TREBEP sólo se aplicarán directamente cuando así lo disponga su legislación específica a:","opciones":["El personal estatutario de los servicios de salud.","El personal militar de las Fuerzas Armadas.","El personal de las Universidades Públicas.","Los Cuerpos de Policía Local."],"bloque":"ambito","precepto":"Art. 4.d del TREBEP","correcta":1,"justificaciones":["No. El personal estatutario de los servicios de salud se rige por su legislación específica y por el Estatuto (**art. 2.3**). No está en la lista del art. 4.","Es esta. El personal militar de las Fuerzas Armadas está en el **art. 4.d**: solo se le aplica el Estatuto directamente cuando lo disponga su legislación específica.","No. Las Universidades Públicas están en el ámbito de aplicación directa (**art. 2.1.e**).","No. Los Cuerpos de Policía Local se rigen también por el Estatuto (**art. 3.2**), con la excepción de la ley orgánica de fuerzas y cuerpos de seguridad."]},{"id":"au-01-010","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 1) - arts. 1 a 8","n":10,"enunciado":"Señale la respuesta incorrecta. Según el TREBEP, las disposiciones del Estatuto Básico del Empleado Público solo se aplicarán directamente cuando así lo disponga su legislación específica al siguiente personal:","opciones":["Personal de las Fuerzas y Cuerpos de Seguridad.","Personal funcionario de las asambleas legislativas de las comunidades autónomas.","Personal del Banco de España.","Personal de los organismos públicos vinculados o dependientes de cualquiera de las Administraciones Públicas."],"bloque":"ambito","precepto":"Arts. 2.1.d y 4 del TREBEP","correcta":3,"justificaciones":["Es verdadera, así que no se marca. El personal de las Fuerzas y Cuerpos de Seguridad está en el **art. 4.e**.","Es verdadera, así que no se marca. El personal funcionario de las asambleas legislativas autonómicas está en el **art. 4.a**.","Es verdadera, así que no se marca. El personal del Banco de España está en el **art. 4.h**.","Esta es la falsa, y por eso es la que hay que marcar. Los organismos públicos y entidades de derecho público vinculados o dependientes de las Administraciones Públicas están en el **art. 2.1.d**: el Estatuto se les aplica directamente."]},{"id":"au-01-011","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 1) - arts. 1 a 8","n":11,"enunciado":"Conforme a su artículo 2, las disposiciones del TREBEP no se aplican directamente al personal funcionario al servicio de:","opciones":["La Administración General del Estado.","Las Cortes Generales.","Las Administraciones de las Comunidades autónomas.","Las Universidades Públicas."],"bloque":"ambito","precepto":"Arts. 2.1 y 4.a del TREBEP","correcta":1,"justificaciones":["No. La Administración General del Estado es el primer supuesto del **art. 2.1.a**: el Estatuto se aplica directamente.","Es esta. El personal funcionario de las Cortes Generales está en el **art. 4.a**: solo se aplica directamente si su legislación específica lo dispone.","No. Las Administraciones de las comunidades autónomas están en el **art. 2.1.b**: aplicación directa.","No. Las Universidades Públicas están en el **art. 2.1.e**: aplicación directa."]},{"id":"au-01-012","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 1) - arts. 1 a 8","n":12,"enunciado":"Señale la respuesta correcta. Las disposiciones del Estatuto Básico del Empleado Público se aplicarán directamente al personal funcionario al servicio de la Administración de Justicia:","opciones":["Solo cuando así lo disponga su legislación específica.","En todo caso.","En ningún caso.","Salvo cuando así lo disponga su legislación específica."],"bloque":"ambito","precepto":"Art. 4.c del TREBEP","correcta":0,"justificaciones":["Es esta. Jueces, Magistrados, Fiscales y demás personal funcionario al servicio de la Administración de Justicia están en el **art. 4.c**: el Estatuto solo se les aplica directamente cuando lo disponga su legislación específica.","No. “En todo caso” contradice el **art. 4**, que condiciona la aplicación a lo que diga su legislación específica.","No. No es “en ningún caso”: si su legislación específica lo dispone, se aplica.","No. No se aplica salvo cuando lo disponga su legislación, sino al revés: solo se aplica cuando lo disponga."]},{"id":"au-01-013","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 1) - arts. 1 a 8","n":13,"enunciado":"Conforme al artículo 5 del TREBEP, ¿por que normativa se rige el personal funcionario de Correos y Telégrafos?","opciones":["Por lo dispuesto en este Estatuto y supletoriamente por sus normas específicas.","Por sus normas específicas y supletoriamente por lo dispuesto en este Estatuto.","Por la legislación laboral y demás normas convencionalmente aplicables.","Por sus normas específicas, exclusivamente."],"bloque":"ambito","precepto":"Art. 5 del TREBEP","correcta":1,"justificaciones":["No. Has invertido el orden. El Estatuto es supletorio, no la norma principal.","Es esta. El **art. 5** dice que el personal funcionario de Correos y Telégrafos se rige por sus normas específicas y supletoriamente por el Estatuto.","No. La legislación laboral es para su personal laboral, no para el funcionario.","No. No es “exclusivamente” por sus normas específicas: el Estatuto se aplica de forma supletoria."]},{"id":"au-01-014","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 1) - arts. 1 a 8","n":14,"enunciado":"En materia de permisos de nacimiento, adopción, del progenitor diferente de la madre biológica y lactancia, el personal laboral al servicio de las Administraciones públicas se rige por:","opciones":["La legislación laboral y por las demás normas convencionalmente aplicables.","Lo previsto en el Estatuto Básico del Empleado Público.","Las previsiones del texto refundido de la Ley del Estatuto de los Trabajadores.","Lo previsto en el convenio colectivo que le resulte de aplicación, exclusivamente."],"bloque":"ambito","precepto":"Art. 7 del TREBEP","correcta":1,"justificaciones":["No. La legislación laboral rige al personal laboral con carácter general, pero en estos permisos el **art. 7** manda aplicar el Estatuto.","Es esta. Desde el Real Decreto-ley 9/2025, el **art. 7** dice que en materia de permisos de nacimiento, adopción, del progenitor diferente de la madre biológica, lactancia y parental, el personal laboral se rige por el Estatuto.","No. El **art. 7** dice expresamente que no se le aplican las previsiones del Estatuto de los Trabajadores sobre las suspensiones de contrato por esos supuestos.","No. No es “exclusivamente” el convenio: manda el Estatuto Básico para esos permisos."]},{"id":"au-01-015","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 1) - arts. 1 a 8","n":15,"enunciado":"Según el artículo 6 del TREBEP, en desarrollo de este Estatuto aprobarán, en el ámbito de sus competencias, leyes reguladoras de la Función Pública:","opciones":["Las Cortes Generales y las asambleas legislativas de las comunidades autónomas.","Las Cortes Generales, las asambleas legislativas de las comunidades autónomas y las entidades locales.","Las Cortes Generales, únicamente.","El TREBEP no precisa de legislación que lo desarrolle."],"bloque":"ambito","precepto":"Art. 6 del TREBEP","correcta":0,"justificaciones":["Es esta. El **art. 6** dice que las Cortes Generales y las asambleas legislativas de las comunidades autónomas aprobarán, en el ámbito de sus competencias, las leyes de Función Pública.","No. Las entidades locales no aprueban leyes. El **art. 6** solo habla de las Cortes Generales y de las asambleas autonómicas.","No. No son “únicamente” las Cortes: también las asambleas legislativas de las comunidades autónomas.","No. El Estatuto sí necesita leyes de desarrollo, como dice su **art. 6**."]},{"id":"au-02-001","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 2) - arts. 9 a 13","n":1,"enunciado":"Conforme al artículo 8.2 del TREBEP, los empleados públicos se clasifican en:","opciones":["Funcionarios de carrera, funcionarios interinos, personal laboral, personal eventual y personal estatutario.","Funcionarios de carrera, funcionarios interinos y personal estatutario.","Funcionarios de carrera, funcionarios interinos, personal laboral y personal eventual.","Funcionarios de carrera, personal laboral y personal estatutario."],"bloque":"clases","precepto":"Art. 8.2 del TREBEP","correcta":2,"justificaciones":["No. El personal estatutario no es una clase del art. 8.2. El Estatuto lo trata aparte (art. 2.3).","No. Faltan el personal laboral y el eventual, y sobra el personal estatutario.","Es esta. El **art. 8.2** clasifica a los empleados públicos en funcionarios de carrera, funcionarios interinos, personal laboral y personal eventual.","No. Faltan los interinos y los eventuales, y sobra el estatutario."]},{"id":"au-02-002","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 2) - arts. 9 a 13","n":2,"enunciado":"Según el artículo 9.2 del TREBEP, el ejercicio de funciones que impliquen participación directa o indirecta en el ejercicio de las potestades públicas de las administraciones públicas corresponde:","opciones":["A todos los empleados públicos.","A todos los empleados públicos, excepto al personal con vinculación de carácter temporal.","A los funcionarios públicos, exclusivamente.","A los funcionarios públicos y al personal laboral."],"bloque":"clases","precepto":"Art. 9.2 del TREBEP","correcta":2,"justificaciones":["No. No todos los empleados públicos pueden ejercer potestades públicas.","No. El personal temporal no es el criterio. Lo es la condición de funcionario.","Es esta. El **art. 9.2** reserva exclusivamente a los funcionarios públicos las funciones de participación directa o indirecta en el ejercicio de potestades públicas.","No. El personal laboral no puede ejercer esas funciones (art. 9.2, y art. 11.2 que lo recuerda)."]},{"id":"au-02-003","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 2) - arts. 9 a 13","n":3,"enunciado":"Conforme al artículo 10 del TREBEP, podrá nombrarse personal interino para la ejecución de programas de carácter temporal, que no podrán tener una duración superior a:","opciones":["Dos años, ampliable hasta doce meses más por las leyes de función pública que se dicten en desarrollo del Estatuto.","Tres años, ampliable hasta seis meses más por las leyes de función pública que se dicten en desarrollo del Estatuto.","Tres años, ampliable hasta doce meses más por las leyes de función pública que se dicten en desarrollo del Estatuto.","Dos años, ampliable hasta seis meses más por las leyes de función pública que se dicten en desarrollo del Estatuto."],"bloque":"clases","precepto":"Art. 10.1.c del TREBEP","correcta":2,"justificaciones":["No. El plazo es de tres años, no de dos.","No. La ampliación es de doce meses, no de seis.","Es esta. El **art. 10.1.c** dice que los programas temporales no pueden durar más de tres años, ampliable hasta doce meses más.","No. Ni dos años ni seis meses: son tres años y doce meses."]},{"id":"au-02-004","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 2) - arts. 9 a 13","n":4,"enunciado":"A los funcionarios interinos les será aplicable, en cuanto sea adecuado a su naturaleza, el régimen general de:","opciones":["El personal laboral.","El personal eventual.","Los funcionarios en prácticas.","Los funcionarios de carrera."],"bloque":"clases","precepto":"Art. 10.5 del TREBEP","correcta":3,"justificaciones":["No. El personal laboral se rige por la legislación laboral, no es el régimen supletorio de los interinos.","No. El personal eventual tiene su propio régimen (art. 12).","No. Los funcionarios en prácticas no son el régimen de referencia de los interinos.","Es esta. El **art. 10.5** dice que se les aplica el régimen general de los funcionarios de carrera, en cuanto sea adecuado a su naturaleza temporal."]},{"id":"au-02-005","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 2) - arts. 9 a 13","n":5,"enunciado":"Conforme al artículo 13 del TREBEP, cuando reúna la condición de personal laboral, el personal directivo:","opciones":["Estará sometido al régimen general de los funcionarios de carrera.","Estará sometido al régimen general del personal laboral.","Estará sometido a la relación laboral de carácter especial de alta dirección.","Estará sometido al régimen general del personal eventual."],"bloque":"clases","precepto":"Art. 13.4 del TREBEP","correcta":2,"justificaciones":["No. Cuando el directivo es personal laboral no se le aplica el régimen de los funcionarios.","No. No es el régimen general del personal laboral, sino uno especial.","Es esta. El **art. 13.4** dice que, cuando reúna la condición de personal laboral, estará sometido a la relación laboral de carácter especial de alta dirección.","No. El personal eventual es otra clase de empleado público."]},{"id":"au-02-006","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 2) - arts. 9 a 13","n":6,"enunciado":"Señale la respuesta correcta en relación con el personal directivo, conforme a lo previsto en el artículo 13 del TREBEP:","opciones":["Su designación no precisará de publicidad ni concurrencia.","No estará sujeto a evaluación, ni responsabilidad por su gestión.","La determinación de sus condiciones de empleo no tendrá la consideración de materia objeto de negociación colectiva.","Estará sometido, en todo caso, a una relación laboral de carácter especial de alta dirección."],"bloque":"clases","precepto":"Art. 13 del TREBEP","correcta":2,"justificaciones":["No. Su designación atiende a mérito, capacidad e idoneidad y debe garantizar publicidad y concurrencia (**art. 13.2**).","No. Está sujeto a evaluación y responde por su gestión (**art. 13.3**).","Es esta. El **art. 13.4** dice que la determinación de sus condiciones de empleo no es materia de negociación colectiva.","No. Solo se le aplica la relación laboral de alta dirección cuando reúna la condición de personal laboral, no “en todo caso”."]},{"id":"au-02-007","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 2) - arts. 9 a 13","n":7,"enunciado":"En relación con el personal directivo, el TREBEP determina que en su designación se atenderá a los principios de:","opciones":["Mérito y capacidad.","Mérito, capacidad y profesionalidad.","Profesionalidad, igualdad y mérito.","Capacidad e idoneidad."],"bloque":"clases","precepto":"Art. 13.2 del TREBEP","correcta":0,"justificaciones":["Es esta. El **art. 13.2** dice que su designación atenderá a principios de mérito y capacidad y a criterios de idoneidad.","No. La profesionalidad no aparece como principio en el art. 13.2.","No. Ni profesionalidad ni igualdad aparecen en ese apartado.","No. Falta el mérito y la idoneidad es un criterio, no un principio."]},{"id":"au-02-008","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 2) - arts. 9 a 13","n":8,"enunciado":"De conformidad con el TREBEP, el personal directivo estará sujeto a evaluación con arreglo a los criterios de:","opciones":["Eficacia y eficiencia.","Mérito y capacidad.","Idoneidad.","Publicidad y concurrencia."],"bloque":"clases","precepto":"Art. 13.3 del TREBEP","correcta":0,"justificaciones":["Es esta. El **art. 13.3** dice que estará sujeto a evaluación con arreglo a los criterios de eficacia y eficiencia, responsabilidad por su gestión y control de resultados.","No. Mérito y capacidad son los principios de su designación, no de su evaluación.","No. La idoneidad es un criterio de designación, no de evaluación.","No. Publicidad y concurrencia son las garantías del procedimiento de designación."]},{"id":"au-02-009","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 2) - arts. 9 a 13","n":9,"enunciado":"El personal que, en virtud de nombramiento y con carácter no permanente, solo realiza funciones expresamente calificadas como de confianza o asesoramiento especial, siendo retribuido con cargo a créditos consignados para este fin se denomina:","opciones":["Personal funcionario interino.","Personal directivo profesional.","Personal eventual.","Personal laboral."],"bloque":"clases","precepto":"Art. 12.1 del TREBEP","correcta":2,"justificaciones":["No. El interino sustituye o desempeña funciones propias de funcionarios de carrera.","No. El directivo desarrolla funciones directivas profesionales.","Es esta. El **art. 12.1** define al personal eventual así: nombramiento, carácter no permanente, funciones de confianza o asesoramiento especial y retribución con cargo a créditos presupuestarios para ese fin.","No. El personal laboral lo es por contrato de trabajo, no por nombramiento."]},{"id":"au-02-010","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 2) - arts. 9 a 13","n":10,"enunciado":"Conforme al TREBEP, no tendrán la consideración de materia objeto de negociación colectiva a los efectos de este Estatuto, la determinación de las condiciones de empleo de:","opciones":["El personal eventual.","El personal laboral.","El personal directivo profesional.","a) y c) son correctas."],"bloque":"clases","precepto":"Art. 13.4 del TREBEP","correcta":2,"justificaciones":["No. Para el personal eventual el art. 13.4 no dice nada.","No. Las condiciones del personal laboral sí se negocian.","Es esta. El **art. 13.4** excluye de la negociación colectiva la determinación de las condiciones de empleo del personal directivo.","No. Solo es correcta la c), no la a): el personal eventual no está en esa exclusión."]},{"id":"au-02-011","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 2) - arts. 9 a 13","n":11,"enunciado":"Señale la respuesta incorrecta en relación con el personal eventual, conforme a lo dispuesto en el artículo 12 del TREBEP:","opciones":["Sus condiciones retributivas no serán públicas.","La condición de personal eventual no podrá constituir mérito para el acceso a la Función Pública o para la promoción interna.","Su nombramiento y cese serán libres.","El número máximo se establecerá por los respectivos órganos de gobierno."],"bloque":"clases","precepto":"Art. 12 del TREBEP","correcta":0,"justificaciones":["Esta es la falsa, y por eso es la que hay que marcar. El **art. 12.2** dice que el número máximo y las condiciones retributivas serán públicas.","Es verdadera, así que no se marca. Es el **art. 12.4**.","Es verdadera, así que no se marca. Lo dice el **art. 12.3**.","Es verdadera, así que no se marca. El número máximo lo fijan los respectivos órganos de gobierno (**art. 12.2**)."]},{"id":"au-02-012","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 2) - arts. 9 a 13","n":12,"enunciado":"El personal laboral al servicio de las Administraciones Públicas:","opciones":["En función de la duración del contrato podrá ser fijo o temporal.","En función de la duración del contrato podrá ser fijo, por tiempo indefinido o temporal.","No podrá ser temporal en ningún caso.","Tendrá siempre la consideración de personal fijo."],"bloque":"clases","precepto":"Art. 11.1 del TREBEP","correcta":1,"justificaciones":["No. Falta la categoría “por tiempo indefinido”: son tres, no dos.","Es esta. El **art. 11.1** dice que, en función de la duración del contrato, el personal laboral puede ser fijo, por tiempo indefinido o temporal.","No. Sí puede ser temporal.","No. No es siempre fijo: puede ser fijo, indefinido o temporal."]},{"id":"au-02-013","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 2) - arts. 9 a 13","n":13,"enunciado":"Señale la respuesta incorrecta respecto al personal eventual al servicio de la Administración Pública:","opciones":["Su nombramiento y cese serán libres.","Le será aplicable, en lo que sea adecuado a la naturaleza de su condición, el régimen general de los funcionarios de carrera.","La condición de personal eventual podrá constituir mérito para el acceso a la Función Pública.","Cesará, en todo caso, cuando cese la autoridad a la que se preste la función de confianza o asesoramiento."],"bloque":"clases","precepto":"Art. 12 del TREBEP","correcta":2,"justificaciones":["Es verdadera, así que no se marca. **Art. 12.3**.","Es verdadera, así que no se marca. **Art. 12.5**.","Esta es la falsa, y por eso es la que hay que marcar. El **art. 12.4** dice justo lo contrario: no podrá constituir mérito para el acceso ni para la promoción interna.","Es verdadera, así que no se marca. **Art. 12.3**."]},{"id":"au-02-014","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 2) - arts. 9 a 13","n":14,"enunciado":"De acuerdo con el TREBEP, ¿cuál es el número máximo de personal eventual de que podrán disponer los órganos de gobierno de las Administraciones Públicas?","opciones":["El que se establezca por sus respectivos órganos de gobierno.","El que se establezca en la Ley de Presupuestos Generales del Estado.","Un número que no supere el diez por ciento del total de la plantilla.","No se establecerá número máximo, pero sí un límite de créditos presupuestarios para la retribución de este personal."],"bloque":"clases","precepto":"Art. 12.2 del TREBEP","correcta":0,"justificaciones":["Es esta. El **art. 12.2** dice que el número máximo se establecerá por los respectivos órganos de gobierno.","No. No lo fija la Ley de Presupuestos Generales del Estado.","No. El Estatuto no pone un tope del diez por ciento.","No. Sí hay un máximo: lo fijan los órganos de gobierno. Los créditos presupuestarios son el origen de la retribución, no el límite del número."]},{"id":"au-02-015","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 2) - arts. 9 a 13","n":15,"enunciado":"De acuerdo con el TREBEP, señale la respuesta correcta relación con los funcionarios interinos:","opciones":["Les será aplicable, en cuanto sea adecuado a la naturaleza de su condición, el régimen general de los funcionarios de carrera.","Son nombrados por razones de necesidad, no así de urgencia.","Sus funciones son diferentes a las que desempeña un funcionario de carrera.","Dada la necesidad, su selección se realizará por procedimientos ágiles sin sujeción a los principios de mérito y publicidad."],"bloque":"clases","precepto":"Art. 10.5 del TREBEP","correcta":0,"justificaciones":["Es esta. El **art. 10.5** les aplica el régimen general de los funcionarios de carrera en cuanto sea adecuado a su naturaleza temporal.","No. Se nombran por razones de necesidad y urgencia (**art. 10.1**).","No. Desempeñan funciones propias de funcionarios de carrera (**art. 10.1**).","No. Su selección sí respeta los principios de igualdad, mérito, capacidad, publicidad y celeridad (**art. 10.2**)."]},{"id":"au-02-016","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 2) - arts. 9 a 13","n":16,"enunciado":"Podrán nombrarse funcionarios interinos por exceso o acumulación de tareas:","opciones":["Por plazo máximo de doce meses, dentro de un periodo de dieciocho meses.","Por plazo máximo de nueve meses, dentro de un periodo de dieciocho meses.","Por plazo máximo de seis meses, dentro de un periodo de doce meses.","Por plazo máximo de doce meses, dentro de un periodo de veinticuatro meses."],"bloque":"clases","precepto":"Art. 10.1.d del TREBEP","correcta":1,"justificaciones":["No. No son doce meses dentro de dieciocho.","Es esta. El **art. 10.1.d** vigente dice por plazo máximo de nueve meses, dentro de un periodo de dieciocho meses.","No. Seis meses dentro de doce era la redacción anterior. Hoy es nueve dentro de dieciocho.","No. No son doce meses dentro de veinticuatro."],"ojo":"La redacción antigua del art. 10.1.d decía seis meses dentro de doce. Se cambió a nueve dentro de dieciocho.","revisar":"Respondida con el texto vigente. Si el profesor corrige con la redacción antigua (seis y doce), la clave sería la opción 3."},{"id":"au-02-017","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 2) - arts. 9 a 13","n":17,"enunciado":"Según lo establecido en el artículo 8 del TREBEP, son empleados públicos quienes desempeñan:","opciones":["Funciones retribuidas en cualquier organización o entidad participada por una Administración Pública.","Funciones retribuidas o no, en las Administraciones Publicas, al servicio de los intereses generales.","Funciones retribuidas en las Administraciones Públicas al servicio de los intereses generales.","Funciones, retribuidas o no, en las Administraciones General del Estado, al servicio de los intereses generales."],"bloque":"clases","precepto":"Art. 8.1 del TREBEP","correcta":2,"justificaciones":["No. Son las funciones en las Administraciones Públicas, no en cualquier entidad participada.","No. Las funciones han de ser retribuidas: “retribuidas o no” es falso.","Es esta. El **art. 8.1** dice: quienes desempeñan funciones retribuidas en las Administraciones Públicas al servicio de los intereses generales.","No. No solo la Administración General del Estado, y además las funciones son retribuidas."]},{"id":"au-02-018","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 2) - arts. 9 a 13","n":18,"enunciado":"Según el Texto Refundido de la Ley del Estatuto Básico del Empleado Público, son funcionarios de carrera quienes, en virtud de nombramiento legal, están vinculados a una Administración Pública por una relación estatutaria:","opciones":["Regulada por el Derecho Administrativo para el desempeño de servicios profesionales retribuidos de carácter permanente.","Regulada por el Derecho Administrativo para el desempeño de servicios profesionales retribuidos de carácter no permanente.","Regulada por el Derecho Administrativo para el desempeño de servicios profesionales no retribuidos de carácter permanente.","Regulada por el Derecho laboral para el desempeño de servicios profesionales retribuidos de carácter permanente."],"bloque":"clases","precepto":"Art. 9.1 del TREBEP","correcta":0,"justificaciones":["Es esta. El **art. 9.1** habla de relación estatutaria regulada por el Derecho Administrativo para servicios profesionales retribuidos de carácter permanente.","No. El carácter es permanente, no “no permanente”.","No. Los servicios son retribuidos.","No. La relación es estatutaria, regulada por el Derecho Administrativo, no por el laboral."]},{"id":"au-02-019","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 2) - arts. 9 a 13","n":19,"enunciado":"Conforme al TREBEP, la selección de funcionarios interinos habrá de realizarse mediante procedimientos ágiles que respetarán, en todo caso, los principios de:","opciones":["Proporcionalidad, transparencia, publicidad e integridad.","Igualdad, capacidad, seguridad jurídica y necesidad.","Igualdad, mérito, capacidad, publicidad y celeridad.","Igualdad, mérito, eficacia y eficiencia."],"bloque":"clases","precepto":"Art. 10.2 del TREBEP","correcta":2,"justificaciones":["No. Esos no son los principios del art. 10.2.","No. Capacidad sí, pero seguridad jurídica y necesidad no son los principios.","Es esta. El **art. 10.2** dice que los procedimientos serán públicos y se rigen por los principios de igualdad, mérito, capacidad, publicidad y celeridad.","No. Eficacia y eficiencia son los criterios de evaluación del personal directivo, no de selección de interinos."]},{"id":"au-02-020","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 2) - arts. 9 a 13","n":20,"enunciado":"Señale la respuesta correcta, de conformidad con lo establecido en el TREBEP:","opciones":["Son funcionarios interinos los nombrados como tales para desempeñar funciones propias del personal eventual.","El personal eventual cesará, en todo caso, cuando se produzca el cese de la autoridad que lo nombró.","Las funciones que impliquen ejercicio de potestades públicas corresponden exclusivamente a los funcionarios de carrera.","En función de la duración del contrato, el personal laboral podrá ser fijo, por tiempo indefinido o temporal."],"bloque":"clases","precepto":"Arts. 9, 11 y 12 del TREBEP","correcta":3,"justificaciones":["No. Los interinos desempeñan funciones propias de funcionarios de carrera, no del personal eventual.","No. El **art. 12.3** dice que cesa cuando se produzca el cese de la autoridad “a la que se preste la función de confianza o asesoramiento”, no de la que lo nombró.","No. Las funciones con potestades públicas son de los funcionarios públicos (**art. 9.2**), no solo de los de carrera.","Es esta. Es el **art. 11.1**: fijo, por tiempo indefinido o temporal."],"revisar":"La opción 1 (eventual) se parece mucho al art. 12.3. Le he dado por falsa por decir “que lo nombró” en lugar de “a la que se preste la función”. Si el profesor la da por buena, hay dos correctas."},{"id":"au-03-001","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 3) - arts. 14 a 20","n":1,"enunciado":"El artículo 14 del TREBEP reconoce el derecho a la inamovilidad en la condición de una clase de personal. Señale cuál:","opciones":["Funcionarios de carrera.","Funcionarios de carrera y personal laboral fijo.","Personal laboral fijo.","No se reconoce el derecho a la inamovilidad de ninguna clase de personal."],"bloque":"derechos","precepto":"Art. 14.a del TREBEP","correcta":0,"justificaciones":["Es esta. El **art. 14.a** reconoce la inamovilidad en la condición de funcionario de carrera.","No. El personal laboral no tiene ese derecho en el Estatuto.","No. El personal laboral fijo no tiene reconocida la inamovilidad.","No. Sí se reconoce, a los funcionarios de carrera."]},{"id":"au-03-002","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 3) - arts. 14 a 20","n":2,"enunciado":"Conforme al artículo 15 del TREBEP, los empleados públicos tienen, entre otros, el siguiente derecho individual que se ejerce de forma colectiva:","opciones":["A la inamovilidad en la condición de funcionario de carrera.","Al ejercicio de la huelga, con la garantía del mantenimiento de los servicios esenciales de la comunidad.","A la libre asociación profesional.","A la jubilación."],"bloque":"derechos","precepto":"Art. 15.c del TREBEP","correcta":1,"justificaciones":["No. La inamovilidad es un derecho individual de ejercicio individual (**art. 14.a**).","Es esta. El **art. 15.c** incluye el ejercicio de la huelga, con la garantía de los servicios esenciales, entre los derechos individuales que se ejercen colectivamente.","No. La libre asociación profesional está en el **art. 14.p**, entre los derechos individuales.","No. La jubilación está en el **art. 14.n**."]},{"id":"au-03-003","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 3) - arts. 14 a 20","n":3,"enunciado":"¿Cuál de los siguientes derechos de los empleados públicos es un derecho individual de ejercicio colectivo de acuerdo con el Texto Refundido de la Ley del Estatuto Básico del Empleado Público?","opciones":["Derecho a la libre asociación profesional.","Derecho a la libertad de expresión.","Derecho de reunión.","Derecho a recibir protección eficaz en materia de seguridad y salud en el trabajo."],"bloque":"derechos","precepto":"Art. 15.e del TREBEP","correcta":2,"justificaciones":["No. La libre asociación profesional es un derecho individual (**art. 14.p**).","No. La libertad de expresión es individual (**art. 14.k**).","Es esta. El derecho de reunión es el **art. 15.e**, de ejercicio colectivo.","No. La seguridad y salud es un derecho individual (**art. 14.l**)."]},{"id":"au-03-004","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 3) - arts. 14 a 20","n":4,"enunciado":"Según el artículo 15 del TREBEP, ¿cuál de los siguientes NO es un derecho individual que se ejerce de forma colectiva?","opciones":["La libre asociación profesional.","El de reunión.","La libertad sindical.","El ejercicio de la huelga."],"bloque":"derechos","precepto":"Arts. 14.p y 15 del TREBEP","correcta":0,"justificaciones":["Esta es la que NO es de ejercicio colectivo, y por eso es la que hay que marcar. La libre asociación profesional está en el **art. 14.p**, entre los individuales.","Es de ejercicio colectivo (**art. 15.e**), así que no se marca.","Es de ejercicio colectivo (**art. 15.a**), así que no se marca.","Es de ejercicio colectivo (**art. 15.c**), así que no se marca."]},{"id":"au-03-005","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 3) - arts. 14 a 20","n":5,"enunciado":"Según lo dispuesto en el artículo 17 del TREBEP, la carrera horizontal de los funcionarios de carrera se articula:","opciones":["Sobre un sistema de grupos, grados y categorías.","Sobre un sistema de grupos, grados y niveles.","Sobre un sistema de grados, categorías o escalones de ascenso.","Sobre un sistema de grupos, niveles o escalones de ascenso."],"bloque":"derechos","precepto":"Art. 17.a del TREBEP","correcta":2,"justificaciones":["No. En la carrera horizontal no hay grupos: son grados, categorías o escalones.","No. Tampoco “grupos” ni “niveles”.","Es esta. El **art. 17.a** habla de un sistema de grados, categorías o escalones de ascenso, fijándose la remuneración a cada uno.","No. Ni grupos ni niveles: son grados, categorías o escalones."]},{"id":"au-03-006","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 3) - arts. 14 a 20","n":6,"enunciado":"De acuerdo con el artículo 16.3.a) del TREBEP, la carrera horizontal de los funcionarios públicos consiste en:","opciones":["El ascenso desde un cuerpo o escala de un Subgrupo, o Grupo de clasificación profesional, a otro superior.","El acceso a cuerpos o escalas del mismo Subgrupo profesional.","El ascenso en la estructura de puestos de trabajo por los procedimientos de provisión establecidos.","La progresión de grado, categoría, escalón u otros conceptos análogos, sin necesidad de cambiar de puesto de trabajo."],"bloque":"derechos","precepto":"Art. 16.3.a del TREBEP","correcta":3,"justificaciones":["No. Eso es la promoción interna vertical (**art. 16.3.c**).","No. Eso es la promoción interna horizontal (**art. 16.3.d**).","No. Eso es la carrera vertical (**art. 16.3.b**).","Es esta. La carrera horizontal es la progresión de grado, categoría, escalón u otros conceptos análogos sin cambiar de puesto (**art. 16.3.a**)."]},{"id":"au-03-007","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 3) - arts. 14 a 20","n":7,"enunciado":"El TREBEP determina las modalidades que podrán establecerse para garantizar la carrera profesional de los funcionarios, entre las que se encuentra la “carrera vertical”, que consiste en:","opciones":["La progresión sin necesidad de cambiar de puesto de trabajo.","El acceso a cuerpos o escalas del mismo subgrupo profesional.","El ascenso en la estructura de puestos de trabajo mediante los procedimientos de provisión.","El ascenso desde un cuerpo o escala de un Subgrupo, o un grupo, a otro superior."],"bloque":"derechos","precepto":"Art. 16.3.b del TREBEP","correcta":2,"justificaciones":["No. Eso es la carrera horizontal.","No. Eso es la promoción interna horizontal.","Es esta. La carrera vertical es el ascenso en la estructura de puestos de trabajo por los procedimientos de provisión (**art. 16.3.b**).","No. Eso es la promoción interna vertical."]},{"id":"au-03-008","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 3) - arts. 14 a 20","n":8,"enunciado":"De acuerdo con el TREBEP, ¿a qué elementos pueden alcanzar los efectos de la evaluación del desempeño?","opciones":["Carrera, formación, situaciones administrativas y retribuciones complementarias.","Carrera, inamovilidad en la condición de funcionario, situaciones administrativas y retribuciones básicas.","Carrera, formación, provisión de puestos de trabajo y retribuciones complementarias.","Carrera, formación, provisión de puestos de trabajo y retribuciones tanto básicas como complementarias."],"bloque":"derechos","precepto":"Art. 20.3 del TREBEP","correcta":2,"justificaciones":["No. Las situaciones administrativas no son un efecto de la evaluación.","No. Ni la inamovilidad ni las retribuciones básicas dependen de la evaluación.","Es esta. El **art. 20.3** dice: carrera profesional horizontal, formación, provisión de puestos de trabajo y retribuciones complementarias.","No. Las retribuciones básicas no están afectadas, solo las complementarias."]},{"id":"au-03-009","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 3) - arts. 14 a 20","n":9,"enunciado":"En el Real Decreto Legislativo 5/2015, por el que se aprueba el TREBEP, la carrera profesional se define como:","opciones":["La progresión de grado, categoría, escalón u otros conceptos análogos, sin necesidad de cambiar de puesto de trabajo.","El ascenso en la estructura de puestos de trabajo por los procedimientos de provisión establecidos legalmente.","El acceso a cuerpos o escalas del mismo Subgrupo profesional.","El conjunto ordenado de oportunidades de ascenso y expectativas de progreso profesional."],"bloque":"derechos","precepto":"Art. 16.2 del TREBEP","correcta":3,"justificaciones":["No. Eso es la carrera horizontal, solo una modalidad.","No. Eso es la carrera vertical, otra modalidad.","No. Eso es la promoción interna horizontal.","Es esta. El **art. 16.2** define la carrera profesional como el conjunto ordenado de oportunidades de ascenso y expectativas de progreso profesional conforme a igualdad, mérito y capacidad."]},{"id":"au-03-010","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 3) - arts. 14 a 20","n":10,"enunciado":"Señale la respuesta incorrecta en virtud de lo dispuesto en el TREBEP sobre las reglas que se aplican a la carrera horizontal de los funcionarios de carrera:","opciones":["Los ascensos serán consecutivos, en todo caso.","Podrán valorarse méritos y aptitudes por razón de la especificidad de la función desarrollada y la experiencia adquirida.","Se deberá valorar la evaluación del desempeño.","Se articulará un sistema de grados, categorías o escalones de ascenso fijándose la remuneración a cada uno de ellos."],"bloque":"derechos","precepto":"Art. 17 del TREBEP","correcta":0,"justificaciones":["Esta es la falsa, y por eso es la que hay que marcar. El **art. 17.a** dice que los ascensos serán consecutivos “con carácter general”, salvo excepciones. No “en todo caso”.","Es verdadera, así que no se marca. **Art. 17.b**.","Es verdadera, así que no se marca. **Art. 17.b**.","Es verdadera, así que no se marca. **Art. 17.a**."]},{"id":"au-03-011","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 3) - arts. 14 a 20","n":11,"enunciado":"Señale la respuesta correcta según el TREBEP:","opciones":["El personal laboral tendrá derecho a la promoción profesional","La aplicación de la promoción interna requerirá la aprobación de sistemas objetivos que permitan evaluar el desempeño.","Los funcionarios interinos tendrán derecho a la promoción profesional.","En la carrera horizontal de los funcionarios de carrera los ascensos serán, sin excepciones, consecutivos."],"bloque":"derechos","precepto":"Art. 19.1 del TREBEP","correcta":0,"justificaciones":["Es esta. El **art. 19.1** dice que el personal laboral tendrá derecho a la promoción profesional.","No. Los sistemas objetivos de evaluación del desempeño los exige el **art. 20.5** para la carrera horizontal, no para la promoción interna.","No. El derecho a la promoción profesional es de los funcionarios de carrera (**art. 16.1**) y del personal laboral (**art. 19**).","No. Es “con carácter general”, no “sin excepciones” (**art. 17.a**)."]},{"id":"au-03-012","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 3) - arts. 14 a 20","n":12,"enunciado":"De acuerdo con el TREBEP, ¿cómo se denomina el procedimiento mediante el cual se mide y valora la conducta profesional y el rendimiento o el logro de resultados?","opciones":["Análisis del rendimiento.","Valoración profesional.","Evaluación del desempeño.","Estudio de rendimiento objetivo."],"bloque":"derechos","precepto":"Art. 20.1 del TREBEP","correcta":2,"justificaciones":["No. No es un nombre que use el Estatuto.","No. No es un nombre que use el Estatuto.","Es esta. El **art. 20.1** define la evaluación del desempeño como el procedimiento que mide y valora la conducta profesional y el rendimiento o logro de resultados.","No. No es un nombre que use el Estatuto."]},{"id":"au-03-013","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 3) - arts. 14 a 20","n":13,"enunciado":"Señale la respuesta INCORRECTA. Según el TREBEP, las leyes de Función Pública que se dicten en desarrollo de este Estatuto regularán la carrera profesional aplicable en cada ámbito que podrá consistir, entre otras, en la aplicación aislada o simultánea de alguna o algunas de las siguientes modalidades:","opciones":["Promoción interna vertical.","Carrera vertical.","Carrera horizontal.","Evaluación del desempeño."],"bloque":"derechos","precepto":"Art. 16.3 del TREBEP","correcta":3,"justificaciones":["Es una modalidad (**art. 16.3.c**), así que no se marca.","Es una modalidad (**art. 16.3.b**), así que no se marca.","Es una modalidad (**art. 16.3.a**), así que no se marca.","Esta es la falsa, y por eso es la que hay que marcar. La evaluación del desempeño está en el **art. 20** y no es una modalidad de carrera profesional."]},{"id":"au-03-014","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 3) - arts. 14 a 20","n":14,"enunciado":"El artículo 18 del TREBEP determina una serie de requisitos necesarios para hacer efectivo el derecho a la promoción interna de los funcionarios de carrera. De los siguientes, ¿cuál no es uno de ellos?","opciones":["Poseer los requisitos exigidos para el ingreso en el Cuerpo al que se promociona.","Participar en los correspondientes cursos de preparación para la superación de los procesos selectivos de promoción interna.","Tener una antigüedad de, al menos, dos años de servicio activo en el inferior Subgrupo, o Grupo de clasificación profesional.","Superar las correspondientes pruebas selectivas."],"bloque":"derechos","precepto":"Art. 18.2 del TREBEP","correcta":1,"justificaciones":["Es requisito, así que no es la respuesta. **Art. 18.2**.","Es esta. Participar en cursos de preparación no figura entre los requisitos del **art. 18.2**.","Es requisito, así que no es la respuesta. Dos años de antigüedad en el Subgrupo inferior (**art. 18.2**).","Es requisito, así que no es la respuesta. Superar las pruebas selectivas (**art. 18.2**)."]},{"id":"au-03-015","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 3) - arts. 14 a 20","n":15,"enunciado":"Señale la respuesta correcta en relación con la evaluación del desempeño a que se refiere el artículo 20 del TREBEP:","opciones":["Las Administraciones Públicas determinarán sus efectos en la percepción de las retribuciones básicas.","La continuidad en un puesto de trabajo obtenido por promoción interna quedará vinculada a la evaluación del desempeño.","La aplicación de la carrera horizontal requerirá la aprobación previa de sistemas objetivos de evaluación del desempeño.","Consiste en la progresión de grado, categoría, escalón o conceptos análogos, sin necesidad de cambiar de puesto de trabajo."],"bloque":"derechos","precepto":"Art. 20.5 del TREBEP","correcta":2,"justificaciones":["No. Afecta a las retribuciones complementarias, no a las básicas (**art. 20.3**).","No. La continuidad vinculada a la evaluación es en un puesto obtenido por concurso, no por promoción interna (**art. 20.4**).","Es esta. El **art. 20.5** exige la aprobación previa de sistemas objetivos de evaluación del desempeño para aplicar la carrera horizontal.","No. Eso describe la carrera horizontal, no la evaluación del desempeño."]},{"id":"au-04-001","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 4) - arts. 21 a 30","n":1,"enunciado":"El artículo 23 del TREBEP establece que las retribuciones básicas de los funcionarios se fijan:","opciones":["Por la Ley de Presupuestos Generales del Estado.","Por los respectivos órganos de Gobierno de cada Administración Pública.","Por Real Decreto del Consejo de Ministros.","Por las leyes de Función Pública que se dicten en desarrollo del presente Estatuto."],"bloque":"retribuciones","precepto":"Art. 23 del TREBEP","correcta":0,"justificaciones":["Es esta. El **art. 23** dice que las retribuciones básicas se fijan en la Ley de Presupuestos Generales del Estado.","No. Los órganos de gobierno de cada Administración no fijan las básicas. Eso es para las complementarias a través de sus leyes (**art. 24**).","No. No se fijan por Real Decreto, sino en la Ley de Presupuestos Generales del Estado.","No. Las leyes de Función Pública de cada Administración regulan las complementarias (**art. 24**), no las básicas."]},{"id":"au-04-002","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 4) - arts. 21 a 30","n":2,"enunciado":"De acuerdo con el Real Decreto legislativo 5/2015, de 30 de octubre, por el que se aprueba el TREBEP, las retribuciones básicas que se fijan en la Ley de Presupuestos Generales del Estado, estarán integradas por:","opciones":["El sueldo, los trienios y el complemento de destino.","El sueldo, los trienios, el complemento de destino y el complemento específico.","Única y exclusivamente por el sueldo y los trienios.","El sueldo, el complemento de destino y el complemento específico."],"bloque":"retribuciones","precepto":"Art. 23 del TREBEP","correcta":2,"justificaciones":["No. El complemento de destino es una retribución complementaria, no básica.","No. Ni el complemento de destino ni el específico son básicas.","Es esta. El **art. 23** dice que las básicas están integradas única y exclusivamente por el sueldo y los trienios.","No. Los complementos de destino y específico son retribuciones complementarias."]},{"id":"au-04-003","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 4) - arts. 21 a 30","n":3,"enunciado":"Señale la opción incorrecta. Las retribuciones complementarias se establecerán atendiendo a los siguientes factores:","opciones":["El grado de interés, iniciativa o esfuerzo con que el funcionario desempeña su trabajo y el rendimiento o resultados obtenidos.","La progresión alcanzada por el funcionario dentro del sistema de carrera administrativa.","Los servicios extraordinarios prestados dentro de la jornada normal de trabajo.","La especial dificultad técnica, responsabilidad, dedicación, incompatibilidad exigible para el desempeño de determinados puestos de trabajo o las condiciones en que se desarrolla el trabajo."],"bloque":"retribuciones","precepto":"Art. 24 del TREBEP","correcta":2,"justificaciones":["Es verdadera, así que no se marca. Es el factor del **art. 24.c**.","Es verdadera, así que no se marca. Es el factor del **art. 24.a**.","Esta es la falsa, y por eso es la que hay que marcar. El **art. 24.d** habla de servicios extraordinarios prestados “fuera” de la jornada normal, no dentro.","Es verdadera, así que no se marca. Es el factor del **art. 24.b**."]},{"id":"au-04-004","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 4) - arts. 21 a 30","n":4,"enunciado":"Según el TREBEP, los servicios extraordinarios prestados fuera de la jornada normal de trabajo del personal funcionario, son un factor a tener en cuenta para determinar la cuantía y estructura de:","opciones":["Las retribuciones básicas.","Las retribuciones complementarias.","Las pagas extraordinarias.","Las indemnizaciones por razón del servicio."],"bloque":"retribuciones","precepto":"Art. 24.d del TREBEP","correcta":1,"justificaciones":["No. Las básicas son solo el sueldo y los trienios (**art. 23**).","Es esta. Los servicios extraordinarios fuera de la jornada son un factor de las retribuciones complementarias (**art. 24.d**).","No. Las pagas extraordinarias no se determinan por ese factor.","No. Las indemnizaciones por razón del servicio son otra cosa (**art. 28**)."]},{"id":"au-04-005","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 4) - arts. 21 a 30","n":5,"enunciado":"Conforme al TREBEP, la cuantía y estructura de las retribuciones complementarias de los funcionarios se establecerán atendiendo, entre otros, a los siguientes factores. Señale la respuesta incorrecta:","opciones":["La progresión alcanzada por el funcionario dentro del sistema de carrera administrativa.","La antigüedad en la condición de funcionario público.","El grado de interés, iniciativa o esfuerzo con que el funcionario desempeña su trabajo y el rendimiento o resultados obtenidos.","Los servicios extraordinarios prestados fuera de la jornada normal de trabajo."],"bloque":"retribuciones","precepto":"Art. 24 del TREBEP","correcta":1,"justificaciones":["Es un factor del **art. 24.a**, así que no se marca.","Esta es la falsa, y por eso es la que hay que marcar. La antigüedad se retribuye con los trienios, que son retribución básica (**art. 23.b**), no complementaria.","Es un factor del **art. 24.c**, así que no se marca.","Es un factor del **art. 24.d**, así que no se marca."]},{"id":"au-04-006","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 4) - arts. 21 a 30","n":6,"enunciado":"Según el artículo 29 del TREBEP, las cantidades destinadas por las Administraciones Públicas a financiar aportaciones a planes de pensiones, tendrán a todos los efectos la consideración de:","opciones":["Retribuciones básicas.","Retribuciones complementarias.","Retribuciones diferidas.","Pagos en especie."],"bloque":"retribuciones","precepto":"Art. 29 del TREBEP","correcta":2,"justificaciones":["No. No son retribuciones básicas.","No. Tampoco complementarias.","Es esta. El **art. 29** dice que tendrán a todos los efectos la consideración de retribución diferida.","No. No se llaman pagos en especie."]},{"id":"au-04-007","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 4) - arts. 21 a 30","n":7,"enunciado":"Señale la respuesta correcta. El Estatuto Básico del Empleado Público establece en cuanto a los derechos retributivos que:","opciones":["Los funcionarios no podrán percibir indemnizaciones por razón del servicio.","Los funcionarios interinos solo percibirán las retribuciones básicas.","Quienes ejerciten el derecho de huelga no devengarán ni percibirán retribuciones.","La parte de jornada no realizada dará lugar a la deducción proporcional de haberes y tendrá carácter sancionador en todo caso."],"bloque":"retribuciones","precepto":"Arts. 25, 28 y 30 del TREBEP","correcta":2,"justificaciones":["No. Sí perciben indemnizaciones por razón del servicio (**art. 28**).","No. Los interinos perciben también las pagas extraordinarias y complementarias (**art. 25**).","Es esta. Según el **art. 30.2**, quienes ejercitan la huelga no devengan ni perciben retribuciones por el tiempo en esa situación.","No. La deducción de haberes por jornada no realizada no tiene carácter sancionador (**art. 30.1**)."]},{"id":"au-04-008","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 4) - arts. 21 a 30","n":8,"enunciado":"Según el TREBEP, las retribuciones de los funcionarios en prácticas serán determinadas por cada Administración Pública y se corresponderán:","opciones":["Como máximo, a las del sueldo del Subgrupo o Grupo en que aspiren a ingresar.","Como mínimo, a las del sueldo del Subgrupo o Grupo en que aspiren a ingresar.","Como máximo, a las retribuciones básicas del Subgrupo o Grupo en que aspiren a ingresar.","Como mínimo, a las retribuciones básicas del Subgrupo o Grupo en que aspiren a ingresar."],"bloque":"retribuciones","precepto":"Art. 26 del TREBEP","correcta":1,"justificaciones":["No. Es “como mínimo”, no “como máximo”.","Es esta. El **art. 26** dice que, como mínimo, se corresponderán a las del sueldo del Subgrupo o Grupo en que aspiren a ingresar.","No. Es mínimo, y además habla del sueldo, no de las retribuciones básicas.","No. Habla del sueldo, no de las retribuciones básicas (que incluyen trienios)."]},{"id":"au-04-009","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 4) - arts. 21 a 30","n":9,"enunciado":"Las retribuciones de los funcionarios de carrera se clasifican en:","opciones":["Básicas y complementarias.","Ordinarias y extraordinarias.","Extraordinarias y complementarias.","Básicas y globales."],"bloque":"retribuciones","precepto":"Art. 22.1 del TREBEP","correcta":0,"justificaciones":["Es esta. El **art. 22.1** clasifica las retribuciones de los funcionarios de carrera en básicas y complementarias.","No. Ordinarias y extraordinarias no es la clasificación del Estatuto.","No. Las extraordinarias son las pagas, no una categoría de retribución.","No. No existen “retribuciones globales” en esa clasificación."]},{"id":"au-04-010","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 4) - arts. 21 a 30","n":10,"enunciado":"Señale la respuesta correcta en relación con los trienios:","opciones":["Tendrán a todos los efectos la consideración de retribución complementaria.","Consisten en una cantidad, que será igual para cada Subgrupo o Grupo de clasificación profesional.","Tendrán a todos los efectos la consideración de retribución diferida.","Retribuyen la progresión alcanzada por el funcionario dentro del sistema de carrera administrativa."],"bloque":"retribuciones","precepto":"Art. 23.b del TREBEP","correcta":1,"justificaciones":["No. Los trienios son retribuciones básicas (**art. 23.b**).","Es esta. Los trienios son una cantidad igual para cada Subgrupo o Grupo por cada tres años de servicio (**art. 23.b**).","No. La retribución diferida son las aportaciones a planes de pensiones (**art. 29**).","No. Los trienios retribuyen la antigüedad. La progresión en la carrera se retribuye con complementarias (**art. 24.a**)."]},{"id":"au-04-011","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 4) - arts. 21 a 30","n":11,"enunciado":"Señale la respuesta correcta en relación con los funcionarios públicos que ejerciten el derecho de huelga:","opciones":["La deducción de haberes que se efectúe tendrá, en todo caso, carácter sancionador.","Percibirán las retribuciones básicas y los trienios correspondientes al tiempo en que hayan permanecido en esa situación.","No devengarán ni percibirán las retribuciones correspondientes al tiempo en que hayan permanecido en esa situación.","Percibirán las retribuciones básicas correspondientes al tiempo en que hayan permanecido en esa situación."],"bloque":"retribuciones","precepto":"Art. 30.2 del TREBEP","correcta":2,"justificaciones":["No. El **art. 30.2** dice que la deducción no tiene carácter de sanción.","No. No perciben ni básicas ni trienios por ese tiempo.","Es esta. No devengarán ni percibirán las retribuciones correspondientes al tiempo en huelga (**art. 30.2**).","No. Tampoco perciben las básicas por ese tiempo."]},{"id":"au-04-012","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 4) - arts. 21 a 30","n":12,"enunciado":"Según el TREBEP, las retribuciones básicas de los empleados públicos estarán integradas única y exclusivamente por:","opciones":["El sueldo y los trienios.","El sueldo, los trienios y las retribuciones específicas.","El sueldo y los complementos específicos.","El sueldo, los trienios y las pagas extraordinarias."],"bloque":"retribuciones","precepto":"Art. 23 del TREBEP","correcta":0,"justificaciones":["Es esta. Las básicas son única y exclusivamente el sueldo y los trienios (**art. 23**).","No. Las retribuciones específicas son complementarias.","No. El complemento específico es complementario.","No. Los componentes de las pagas extraordinarias están ya incluidos en sueldo y trienios (**art. 22.2**), no son un concepto aparte."]},{"id":"au-04-013","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 4) - arts. 21 a 30","n":13,"enunciado":"Señale la respuesta incorrecta en relación con los funcionarios que ejerciten el derecho de huelga:","opciones":["Se les efectuará deducción de haberes, sin que ello conlleve el ejercicio de potestad sancionadora.","No percibirán las retribuciones correspondientes al tiempo en que hayan permanecido en esa situación.","Se les efectuará deducción de haberes, que no afectará al régimen de sus prestaciones sociales.","Devengarán las retribuciones correspondientes el tiempo en que hayan permanecido en esa situación."],"bloque":"retribuciones","precepto":"Art. 30.2 del TREBEP","correcta":3,"justificaciones":["Es verdadera, así que no se marca. La deducción no tiene carácter sancionador (**art. 30.2**).","Es verdadera, así que no se marca. No perciben retribuciones por ese tiempo.","Es verdadera, así que no se marca. La deducción no afecta a sus prestaciones sociales (**art. 30.2**).","Esta es la falsa, y por eso es la que hay que marcar. No devengan las retribuciones del tiempo de huelga."]},{"id":"au-04-014","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 4) - arts. 21 a 30","n":14,"enunciado":"Señale la respuesta incorrecta en relación con las retribuciones de los funcionarios:","opciones":["Las retribuciones de los funcionarios de carrera se clasifican en básicas y complementarias.","Las pagas extraordinarias, que serán dos al año, comprenderán la totalidad de las retribuciones complementarias.","Las retribuciones complementarias retribuyen, entre otros aspectos, las características de los puestos de trabajo.","No podrá percibirse participación en tributos como contraprestación de cualquier servicio."],"bloque":"retribuciones","precepto":"Art. 22.4 del TREBEP","correcta":1,"justificaciones":["Es verdadera, así que no se marca. **Art. 22.1**.","Esta es la falsa, y por eso es la que hay que marcar. Las pagas extraordinarias incluyen la totalidad de las complementarias salvo las de los apartados c) y d) del art. 24 (**art. 22.4**).","Es verdadera, así que no se marca. **Art. 22.3**.","Es verdadera, así que no se marca. **Art. 22.5**."]},{"id":"au-04-015","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 4) - arts. 21 a 30","n":15,"enunciado":"De acuerdo con el artículo 24 del TREBEP, la cuantía y estructura de las retribuciones complementarias de los funcionarios se establecerán por:","opciones":["Las correspondientes leyes de cada Administración Pública.","Los correspondientes convenios colectivos.","Los órganos de Gobierno de las respectivas Administraciones Públicas.","La Ley de Presupuestos Generales del Estado."],"bloque":"retribuciones","precepto":"Art. 24 del TREBEP","correcta":0,"justificaciones":["Es esta. El **art. 24** dice que se establecen por las correspondientes leyes de cada Administración Pública.","No. No se fijan por convenios colectivos (que son del personal laboral).","No. No son los órganos de gobierno, sino las leyes de cada Administración.","No. La Ley de Presupuestos del Estado fija las básicas (**art. 23**)."]},{"id":"au-04-016","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 4) - arts. 21 a 30","n":16,"enunciado":"Las retribuciones que retribuyen las características de los puestos de trabajo, la carrera profesional o el desempeño alcanzado por el funcionario se denominan:","opciones":["Básicas.","Fijas.","Complementarias.","Variables."],"bloque":"retribuciones","precepto":"Art. 22.3 del TREBEP","correcta":2,"justificaciones":["No. Las básicas retribuyen la adscripción al Subgrupo y la antigüedad (**art. 22.2**).","No. “Fijas” no es una categoría del Estatuto.","Es esta. El **art. 22.3** dice que las complementarias retribuyen las características de los puestos, la carrera profesional o el desempeño.","No. “Variables” no es una categoría del Estatuto."]},{"id":"au-04-017","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 4) - arts. 21 a 30","n":17,"enunciado":"Según el artículo 22 del TREBEP, las pagas extraordinarias de los funcionarios de carrera se compondrán por el importe de una mensualidad de:","opciones":["Las retribuciones básicas, exclusivamente.","Las retribuciones básicas y las retribuciones complementarias a las que se refieren los apartados a) y b) del artículo 24.","Las retribuciones básicas y las retribuciones complementarias a las que se refieren los apartados c) y d) del artículo 24.","Las retribuciones básicas y la totalidad de las retribuciones complementarias."],"bloque":"retribuciones","precepto":"Arts. 22.4 y 24 del TREBEP","correcta":1,"justificaciones":["No. También incluyen las complementarias, salvo las de los apartados c) y d) del art. 24.","Es esta. Una mensualidad de básicas y de las complementarias, salvo c) y d) del art. 24, es decir, las de los apartados a) y b) (**art. 22.4**).","No. Son justo las que se excluyen.","No. No incluyen la totalidad: quedan fuera las de los apartados c) y d)."]},{"id":"au-04-018","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 4) - arts. 21 a 30","n":18,"enunciado":"Señale la respuesta incorrecta en relación con las retribuciones de los funcionarios interinos:","opciones":["Percibirán las retribuciones básicas correspondientes al Subgrupo o Grupo de adscripción.","Salvo excepciones, no percibirán retribuciones complementarias.","Percibirán las pagas extraordinarias correspondientes al Subgrupo o Grupo de adscripción.","Se reconocerán los trienios correspondientes a los servicios prestados antes de la entrada en vigor del TREBEP."],"bloque":"retribuciones","precepto":"Art. 25 del TREBEP","correcta":1,"justificaciones":["Es verdadera, así que no se marca. **Art. 25.1**.","Esta es la falsa, y por eso es la que hay que marcar. Perciben las complementarias de los apartados b), c) y d) del art. 24 y las de la categoría de entrada (**art. 25.1**).","Es verdadera, así que no se marca. **Art. 25.1**.","Es verdadera, así que no se marca. **Art. 25.2**."]},{"id":"au-04-019","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 4) - arts. 21 a 30","n":19,"enunciado":"Las retribuciones del personal laboral se determinarán de acuerdo con:","opciones":["La legislación laboral.","El convenio colectivo que sea aplicable.","El contrato de trabajo.","Todas las respuestas anteriores son correctas."],"bloque":"retribuciones","precepto":"Art. 27 del TREBEP","correcta":3,"justificaciones":["Es correcta, pero no es la única.","Es correcta, pero no es la única.","Es correcta, pero no es la única.","Es esta. El **art. 27** menciona las tres: legislación laboral, convenio colectivo y contrato de trabajo."]},{"id":"au-04-020","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 4) - arts. 21 a 30","n":20,"enunciado":"Los trienios de las pagas extraordinarias y las retribuciones por servicios extraordinarios prestados fuera de la jornada normal de trabajo constituyen:","opciones":["Retribuciones complementarias, en ambos casos.","Retribuciones básicas, los primeros, y complementarias, los segundos.","Retribuciones complementarias, los primeros, y básicas, los segundos.","Retribuciones básicas, en ambos casos."],"bloque":"retribuciones","precepto":"Arts. 22.2 y 24.d del TREBEP","correcta":1,"justificaciones":["No. Los trienios son retribuciones básicas.","Es esta. Los trienios (incluidos los de las pagas extraordinarias) son básicos (**art. 22.2**) y los servicios extraordinarios fuera de jornada son complementarios (**art. 24.d**).","No. Los has invertido.","No. Los servicios extraordinarios son complementarios."]},{"id":"au-05-001","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":1,"enunciado":"¿A qué principios estará sujeta la negociación colectiva de condiciones de trabajo de los funcionarios públicos?","opciones":["De legalidad, jerarquía, eficacia, buena fe negocial, publicidad y transparencia.","De legalidad, eficacia, eficiencia, desconcentración, publicidad y obligatoriedad.","De legalidad, cobertura presupuestaria, obligatoriedad, buena fe negocial, publicidad y transparencia.","De legalidad, jerarquía, desconcentración, buena fe negocial, cobertura presupuestaria y coordinación."],"bloque":"negociacion","precepto":"Art. 33.1 del TREBEP","correcta":2,"justificaciones":["No. La jerarquía y la eficacia no son principios del art. 33.1.","No. Eficacia, eficiencia y desconcentración no están en la lista.","Es esta. El **art. 33.1** cita legalidad, cobertura presupuestaria, obligatoriedad, buena fe negocial, publicidad y transparencia.","No. Ni jerarquía, ni desconcentración, ni coordinación son principios del art. 33.1."]},{"id":"au-05-002","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":2,"enunciado":"¿Cuál de las siguientes materias NO queda excluida de la obligatoriedad de la negociación?","opciones":["La determinación de condiciones de trabajo del personal directivo.","La regulación del ejercicio del derecho de los ciudadanos y de los usuarios de los servicios públicos.","Los criterios generales sobre ofertas de empleo público.","Los poderes de dirección y control propios de la relación jerárquica."],"bloque":"negociacion","precepto":"Art. 37 del TREBEP","correcta":2,"justificaciones":["No. Está excluida (**art. 37.2.c**).","No. Está excluida (**art. 37.2.b**).","Es esta. Los criterios generales sobre ofertas de empleo público son materia de negociación obligatoria (**art. 37.1.l**).","No. Está excluida (**art. 37.2.d**)."]},{"id":"au-05-003","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":3,"enunciado":"Según el TREBEP, salvo que existan causas legales o pactadas que lo impidan, el proceso de negociación se iniciará, desde que la mayoría de una de las partes legitimadas lo promueva, en el plazo máximo de:","opciones":["Seis meses.","Veinte días.","Un mes.","Tres meses."],"bloque":"negociacion","precepto":"Art. 34.6 del TREBEP","correcta":2,"justificaciones":["No. No son seis meses.","No. No son veinte días.","Es esta. A falta de acuerdo, el proceso se inicia en el plazo máximo de un mes (**art. 34.6**).","No. No son tres meses."]},{"id":"au-05-004","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":4,"enunciado":"¿Cuál de las siguientes materias NO ha de ser objeto de negociación obligatoria según el artículo 37 del TREBEP?","opciones":["La determinación de condiciones de trabajo del personal directivo.","Los planes de Previsión Social Complementaria.","Las propuestas sobre derechos sindicales y de participación.","Los criterios generales para la determinación de prestaciones sociales y pensiones de clases pasivas."],"bloque":"negociacion","precepto":"Art. 37.2.c del TREBEP","correcta":0,"justificaciones":["Es esta. La determinación de condiciones de trabajo del personal directivo está excluida de la negociación obligatoria (**art. 37.2.c**).","No. Es materia de negociación (**art. 37.1.e**).","No. Es materia de negociación (**art. 37.1.h**).","No. Es materia de negociación (**art. 37.1.g**)."]},{"id":"au-05-005","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":5,"enunciado":"Según el TREBEP, a efectos de negociación colectiva de los funcionarios públicos se constituye una Mesa General de Negociación de las Administraciones Públicas, que contará con representantes de:","opciones":["Las Comunidades Autónomas.","Las ciudades de Ceuta y Melilla.","La Federación Española de Municipios y Provincias.","Todas las respuestas anteriores son correctas."],"bloque":"negociacion","precepto":"Art. 36.1 del TREBEP","correcta":3,"justificaciones":["Es correcta, pero no es la única.","Es correcta, pero no es la única.","Es correcta, pero no es la única.","Es esta. La Mesa General cuenta con representantes de las Comunidades Autónomas, Ceuta y Melilla y la FEMP (**art. 36.1**)."]},{"id":"au-05-006","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":6,"enunciado":"Según el artículo 34 del TREBEP, en el ámbito de la Administración General del Estado es obligatorio constituir:","opciones":["Una Mesa General de Negociación.","Tanto una Mesa General de Negociación como Mesas Sectoriales.","Mesas Sectoriales de negociación.","La constitución de cualquier Mesa de Negociación es facultativa."],"bloque":"negociacion","precepto":"Art. 34.1 del TREBEP","correcta":0,"justificaciones":["Es esta. Se constituirá una Mesa General de Negociación en la Administración General del Estado (**art. 34.1**).","No. Las Mesas Sectoriales son facultativas: se constituyen por acuerdo de las Mesas Generales (**art. 34.4**).","No. Las Mesas Sectoriales no son obligatorias.","No. La Mesa General sí es obligatoria."]},{"id":"au-05-007","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":7,"enunciado":"Según el artículo 36 del TREBEP, la Mesa General de Negociación de las Administraciones Públicas estará presidida por:","opciones":["La Administración General del Estado.","Representantes de las Comunidades Autónomas.","La Federación Española de Municipios y Provincias.","Rotativamente por todos los anteriores."],"bloque":"negociacion","precepto":"Art. 36.1 del TREBEP","correcta":0,"justificaciones":["Es esta. La Mesa General de las Administraciones Públicas está presidida por la Administración General del Estado (**art. 36.1**).","No. Las Comunidades Autónomas tienen representantes, pero no la presiden.","No. La FEMP tiene representantes, pero no la preside.","No. No hay presidencia rotativa."]},{"id":"au-05-008","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":8,"enunciado":"En el seno de las Mesas de Negociación correspondientes, los representantes de las Administraciones Públicas podrán concertar Pactos y Acuerdos para la determinación de condiciones de trabajo de los funcionarios de dichas Administraciones con:","opciones":["La representación de las organizaciones sindicales legitimadas a tales efectos.","Los Delegados de Personal.","La Junta de Personal.","Cualquiera de los anteriores."],"bloque":"negociacion","precepto":"Art. 38.1 del TREBEP","correcta":0,"justificaciones":["Es esta. Los Pactos y Acuerdos se concertan con las organizaciones sindicales legitimadas (**art. 38.1**).","No. Los delegados de personal son órganos de representación, no negocian Pactos y Acuerdos en la Mesa.","No. La Junta de Personal es un órgano de representación unitaria, no una parte del Pacto.","No. Solo vale la primera."]},{"id":"au-05-009","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":9,"enunciado":"Para el seguimiento de los Pactos y Acuerdos se establecerán, con la composición y funciones que las partes determinen:","opciones":["Mesas Generales de Negociación.","Organizaciones sindicales.","Comisiones Paritarias.","Mesas Sectoriales."],"bloque":"negociacion","precepto":"Art. 38.5 del TREBEP","correcta":2,"justificaciones":["No. Las Mesas Generales son donde se negocia.","No. Las organizaciones sindicales son una de las partes.","Es esta. El **art. 38.5** establece Comisiones Paritarias de seguimiento.","No. Las Mesas Sectoriales negocian, no hacen el seguimiento."],"dup":"au-05-009"},{"id":"au-05-010","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":10,"enunciado":"Según el TREBEP, el derecho a participar, a través de las organizaciones sindicales, en los órganos de control y seguimiento de las entidades u organismos que legalmente se determine, se denomina:","opciones":["Derecho de representación.","Mesas de negociación.","Participación Institucional.","Negociación colectiva."],"bloque":"negociacion","precepto":"Art. 31.4 del TREBEP","correcta":2,"justificaciones":["No. La representación es la facultad de elegir representantes (**art. 31.3**).","No. Las Mesas son órganos de negociación.","Es esta. La participación institucional es el derecho a participar, a través de los sindicatos, en los órganos de control y seguimiento (**art. 31.4**).","No. La negociación colectiva es el derecho a negociar condiciones de trabajo (**art. 31.2**)."]},{"id":"au-05-011","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":11,"enunciado":"De conformidad con el TREBEP, salvo acuerdo en contrario, los Pactos y Acuerdos se prorrogarán:","opciones":["De año en año, siempre que conste la aceptación expresa de todas las partes.","De año en año, si no mediara denuncia expresa de una de las partes.","De mes en mes, siempre que conste la aceptación expresa de todas las partes.","De mes en mes, si no mediara denuncia expresa de una de las partes."],"bloque":"negociacion","precepto":"Art. 38.11 del TREBEP","correcta":1,"justificaciones":["No. No hace falta aceptación expresa: se prorrogan si nadie los denuncia.","Es esta. Salvo acuerdo en contrario, se prorrogan de año en año si no media denuncia expresa de una de las partes (**art. 38.11**).","No. El plazo es de año en año, no de mes en mes.","No. El plazo es de un año."]},{"id":"au-05-012","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":12,"enunciado":"Según el TREBEP, la negociación colectiva de condiciones de trabajo de los funcionarios públicos estará sujeta, entre otros, a los principios de:","opciones":["Cobertura presupuestaria.","Obligatoriedad","Buena fe negocial.","Todas las respuestas anteriores son correctas."],"bloque":"negociacion","precepto":"Art. 33.1 del TREBEP","correcta":3,"justificaciones":["Es un principio del **art. 33.1**, pero no el único.","Es un principio del **art. 33.1**, pero no el único.","Es un principio del **art. 33.1**, pero no el único.","Es esta. Las tres son principios del **art. 33.1**."]},{"id":"au-05-013","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":13,"enunciado":"Conforme al artículo 34.7 del TREBEP, en los procesos de negociación, la Administración correspondiente y la mayoría de la representación sindical están obligadas a proporcionarse mutuamente la información que precisen relativa a la negociación y a negociar bajo el principio de:","opciones":["Cobertura presupuestaria.","Transparencia.","La buena fe.","Publicidad."],"bloque":"negociacion","precepto":"Art. 34.7 del TREBEP","correcta":2,"justificaciones":["No. La cobertura presupuestaria es otro principio del art. 33.1.","No. Es otro principio del art. 33.1, no el del 34.7.","Es esta. El **art. 34.7** dice que ambas partes negociarán bajo el principio de la buena fe.","No. Es otro principio del art. 33.1."]},{"id":"au-05-014","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":14,"enunciado":"De conformidad con lo establecido en el texto refundido de la Ley del Estatuto Básico del Empleado Público, entre los principios a los que está sujeta la negociación colectiva de las condiciones de trabajo de los funcionarios públicos, NO se encuentra:","opciones":["El principio de legalidad.","El principio de cobertura presupuestaria.","El principio de jerarquía.","El principio de obligatoriedad."],"bloque":"negociacion","precepto":"Art. 33.1 del TREBEP","correcta":2,"justificaciones":["Es un principio del **art. 33.1**, así que no se marca.","Es un principio del **art. 33.1**, así que no se marca.","Esta es la que NO está, y por eso es la que hay que marcar. La jerarquía no es un principio de la negociación colectiva.","Es un principio del **art. 33.1**, así que no se marca."]},{"id":"au-05-015","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":15,"enunciado":"Según el TREBEP, quedará excluida de la obligatoriedad de la negociación:","opciones":["La determinación y aplicación de las retribuciones complementarias de los funcionarios.","El procedimiento de formación de los actos y disposiciones administrativas.","Los criterios generales de acción social.","Las normas que fijen los criterios y mecanismos generales en materia de evaluación del desempeño."],"bloque":"negociacion","precepto":"Art. 37.2.b del TREBEP","correcta":1,"justificaciones":["No. Es materia de negociación (**art. 37.1.b**).","Es esta. El procedimiento de formación de los actos y disposiciones administrativas está excluido (**art. 37.2.b**).","No. Es materia de negociación (**art. 37.1.i**).","No. Es materia de negociación (**art. 37.1.d**)."]},{"id":"au-05-016","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":16,"enunciado":"Señale cuál de estas materias queda excluida de la negociación colectiva de los empleados públicos, a tenor de lo previsto en el artículo 37 del TREBEP:","opciones":["Los criterios generales sobre ofertas de empleo público.","Los planes de previsión social complementaria.","La regulación y determinación concreta, en cada caso, de los sistemas de acceso al empleo público.","La determinación y aplicación de las retribuciones complementarias de los funcionarios."],"bloque":"negociacion","precepto":"Art. 37.2.e del TREBEP","correcta":2,"justificaciones":["No. Es materia de negociación (**art. 37.1.l**).","No. Es materia de negociación (**art. 37.1.e**).","Es esta. La regulación y determinación concreta de los sistemas de acceso al empleo público está excluida (**art. 37.2.e**).","No. Es materia de negociación (**art. 37.1.b**)."]},{"id":"au-05-017","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":17,"enunciado":"Conforme al TREBEP, a efectos de negociación colectiva de las condiciones de trabajo de funcionarios públicos, se constituirán Mesas de negociación en las que no estarán legitimadas para estar presentes:","opciones":["Las organizaciones sindicales más representativas a nivel estatal.","Los representantes de la Administración Pública correspondiente.","Las organizaciones sindicales más representativas de Comunidades Autónomas.","Los sindicatos que hayan obtenido el 5% de los representantes en las elecciones para Delegados y Juntas de Personal."],"bloque":"negociacion","precepto":"Art. 33.1 del TREBEP","correcta":3,"justificaciones":["No. Están legitimadas (**art. 33.1**).","No. Están legitimados.","No. Están legitimadas.","Es esta. Los sindicatos necesitan el 10 por 100 o más de los representantes, no el 5 (**art. 33.1**)."]},{"id":"au-05-018","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":18,"enunciado":"¿Cuál de las siguientes materias NO ha de ser objeto de negociación según el artículo 37 del TREBEP?","opciones":["Los criterios generales de los planes y fondos para la formación y la promoción interna.","Los planes de Previsión Social Complementaria.","Las normas que fijen los criterios y mecanismos generales en materia de evaluación del desempeño.","Los poderes de dirección y control propios de la relación jerárquica."],"bloque":"negociacion","precepto":"Art. 37 del TREBEP","correcta":3,"justificaciones":["No. Es materia de negociación (**art. 37.1.f**).","No. Es materia de negociación (**art. 37.1.e**).","No. Es materia de negociación (**art. 37.1.d**).","Es esta. Los poderes de dirección y control propios de la relación jerárquica están excluidos (**art. 37.2.d**)."]},{"id":"au-05-019","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":19,"enunciado":"De acuerdo con el TREBEP, quedan excluidas de la obligatoriedad de la negociación colectiva:","opciones":["Las decisiones de las Administraciones Públicas que afecten a sus potestades de organización.","Los criterios generales sobre oferta de empleo público.","La determinación y aplicación de las retribuciones complementarias de los funcionarios.","Las normas que fijen los mecanismos generales de evaluación del desempeño."],"bloque":"negociacion","precepto":"Art. 37.2.a del TREBEP","correcta":0,"justificaciones":["Es esta. Las decisiones que afecten a las potestades de organización están excluidas (**art. 37.2.a**).","No. Es materia de negociación (**art. 37.1.l**).","No. Es materia de negociación (**art. 37.1.b**).","No. Es materia de negociación (**art. 37.1.d**)."]},{"id":"au-05-020","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":20,"enunciado":"Señale la respuesta correcta en relación con los acuerdos a que se refiere el artículo 38 del TREBEP:","opciones":["Salvo acuerdo en contrario, se prorrogarán cada 5 años si no mediara denuncia expresa de una de las partes.","Se celebrarán sobre materias que correspondan estrictamente al ámbito competencial del órgano que lo suscriba.","Versarán sobre materias competencia de los órganos de gobierno de Administraciones Públicas.","Tendrán eficacia directa, en todo caso."],"bloque":"negociacion","precepto":"Art. 38.3 del TREBEP","correcta":2,"justificaciones":["No. Se prorrogan de año en año, no cada cinco años (**art. 38.11**).","No. Eso describe los Pactos (**art. 38.2**). Los Acuerdos versan sobre materias de los órganos de gobierno.","Es esta. Los Acuerdos versan sobre materias competencia de los órganos de gobierno de las Administraciones Públicas (**art. 38.3**).","No. No siempre tienen eficacia directa: si tratan materias de reserva de ley, carecen de ella (**art. 38.3**)."]},{"id":"au-05-021","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":21,"enunciado":"A efectos del Real Decreto Legislativo 5/2015, el derecho a negociar la determinación de condiciones de trabajo de los empleados de las Administraciones Públicas, se entiende como:","opciones":["Negociación institucional.","Negociación colectiva.","Pactos colectivos.","Acuerdos institucionales."],"bloque":"negociacion","precepto":"Art. 31.2 del TREBEP","correcta":1,"justificaciones":["No. No existe como tal en el Estatuto.","Es esta. Es el derecho a negociar la determinación de condiciones de trabajo (**art. 31.2**).","No. Los Pactos son el resultado de la negociación.","No. Los Acuerdos son el resultado de la negociación."]},{"id":"au-05-022","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":22,"enunciado":"Están legitimados para la interposición de recursos en vía administrativa y jurisdiccional contra las resoluciones de los órganos de selección:","opciones":["Los empleados públicos.","Los órganos de control y seguimiento de las Administraciones Públicas.","Las organizaciones sindicales más representativas en el ámbito de la Función Pública.","Cualquier organización sindical."],"bloque":"negociacion","precepto":"Art. 31.6 del TREBEP","correcta":2,"justificaciones":["No. El Estatuto no legitima a todos los empleados públicos en este supuesto.","No. Los órganos de control no recurren.","Es esta. Las organizaciones sindicales más representativas en el ámbito de la Función Pública están legitimadas (**art. 31.6**).","No. No vale cualquier organización sindical, solo las más representativas."]},{"id":"au-05-023","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":23,"enunciado":"En la composición numérica de las Mesas Generales de Negociación:","opciones":["Ninguna de las partes puede superar los siete miembros.","Ninguna de las partes puede superar los nueve miembros.","Ninguna de las partes puede superar el número de once miembros.","Ninguna de las partes puede superar el número de quince miembros."],"bloque":"negociacion","precepto":"Art. 35.4 del TREBEP","correcta":3,"justificaciones":["No. El tope es quince.","No. El tope es quince.","No. El tope es quince.","Es esta. Ninguna de las partes puede superar el número de quince miembros (**art. 35.4**)."]},{"id":"au-05-024","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":24,"enunciado":"¿Por quién estará presidida la Mesa General de Negociación de las Administraciones Públicas?","opciones":["Por los Delegados de Personal.","Por el Comité de Empresa.","Por la Administración General del Estado.","Por la Junta de Personal."],"bloque":"negociacion","precepto":"Art. 36.1 del TREBEP","correcta":2,"justificaciones":["No. Los delegados de personal son órganos de representación.","No. El Comité de Empresa es órgano de representación del personal laboral.","Es esta. La preside la Administración General del Estado (**art. 36.1**).","No. La Junta de Personal es órgano de representación."]},{"id":"au-05-025","origen":"autoevaluacion","test":"TREBEP (Autoevaluación 5) - arts. 31 a 38","n":25,"enunciado":"Cuando exista falta de ratificación de un Acuerdo o, en su caso, una negativa expresa a incorporar lo acordado en el proyecto de ley correspondiente se deberá iniciar la renegociación de las materias tratadas:","opciones":["En el plazo de un mes, si así lo solicitara al menos la mayoría de una de las partes.","En el plazo de un mes, si así lo solicitara al menos los dos tercios de una de las partes.","En el plazo de un año, si así lo solicitara al menos la mayoría de una de las partes.","En el plazo de un año, si así lo solicitara al menos los dos tercios de una de las partes."],"bloque":"negociacion","precepto":"Art. 38.3 del TREBEP","correcta":0,"justificaciones":["Es esta. Se renegocia en el plazo de un mes si lo solicita al menos la mayoría de una de las partes (**art. 38.3**).","No. No son los dos tercios.","No. El plazo es de un mes, no de un año.","No. Ni un año ni dos tercios."]},{"id":"vo-02-011","origen":"votaciones","test":"TREBEP (Votación Clase 2)","n":11,"enunciado":"Para el seguimiento de los Pactos y Acuerdos se establecerán, con la composición y funciones que las partes determinen:","opciones":["Mesas Generales de Negociación.","Organizaciones sindicales.","Comisiones Paritarias.","Mesas Sectoriales."],"bloque":"negociacion","precepto":"Art. 38.5 del TREBEP","correcta":2,"justificaciones":["No. Las Mesas Generales son donde se negocia.","No. Las organizaciones sindicales son una de las partes.","Es esta. El **art. 38.5** establece Comisiones Paritarias de seguimiento.","No. Las Mesas Sectoriales negocian, no hacen el seguimiento."],"dup":"au-05-009"}]});
